INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Desktop as a Service dasselbe wie ein lokaler PC?', 2, '[{"text": "Nein", "correct": true, "because": "DaaS läuft in der Cloud"}, {"text": "Ja", "correct": false, "because": "Lokaler PC ist physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ist für DaaS typisch?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Flexibel anpassbar"}, {"text": "Hohe Anfangskosten", "correct": false, "because": "DaaS ist abonnementbasiert"}, {"text": "Lokale Wartung", "correct": false, "because": "Cloud verwaltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen DaaS nützlich?', 5, '[{"text": "Remote-Zugriff", "correct": true, "because": "Arbeiten von überall"}, {"text": "Zentralisierte Verwaltung", "correct": true, "because": "IT vereinfacht"}, {"text": "Hohe Latenz", "correct": false, "because": "Ziel ist geringe Latenz"}, {"text": "Physische Hardware", "correct": false, "because": "Cloud-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DaaS spart Hardwarekosten. b) Es erfordert lokale Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Server sind in der Cloud"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DaaS?', 4, '[{"text": "Internetverbindung", "correct": false, "because": "Notwendig für Zugriff"}, {"text": "Sicherheitsupdates", "correct": false, "because": "Provider verwaltet"}, {"text": "Lokale Installation", "correct": true, "because": "Alles in der Cloud"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DaaS nur für Windows geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Unterstützt auch Linux"}, {"text": "Ja", "correct": false, "because": "Mehrere OS möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Anbieter ist bekannt für DaaS?', 3, '[{"text": "Citrix", "correct": true, "because": "Führend bei Virtualisierung"}, {"text": "Adobe", "correct": false, "because": "Fokus auf Kreativsoftware"}, {"text": "Oracle", "correct": false, "because": "Datenbankfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien profitieren von DaaS?', 5, '[{"text": "Remote-Arbeit", "correct": true, "because": "Zugriff von überall"}, {"text": "Temporäre Teams", "correct": true, "because": "Schnelle Bereitstellung"}, {"text": "Lokale Entwicklung", "correct": false, "because": "Cloud-fokussiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DaaS erhöht Sicherheit. b) Es braucht viel lokale Leistung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lokale Geräte sind Thin Clients"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DaaS?', 4, '[{"text": "Cloud-Abonnement", "correct": false, "because": "Grundlage von DaaS"}, {"text": "Internet", "correct": false, "because": "Zugriff erforderlich"}, {"text": "Lokaler Server", "correct": true, "because": "Cloud übernimmt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DaaS dasselbe wie VDI?', 2, '[{"text": "Nein", "correct": true, "because": "VDI ist lokal, DaaS Cloud"}, {"text": "Ja", "correct": false, "because": "Unterschied in Hosting"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte unterstützt DaaS typischerweise?', 4, '[{"text": "Laptops", "correct": true, "because": "Flexibler Zugriff"}, {"text": "Tablets", "correct": true, "because": "Mobile Nutzung"}, {"text": "Drucker", "correct": false, "because": "Kein Zugriffspunkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DaaS nur für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs nutzen es"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines DaaS-Anbieters?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Datenschutz entscheidend"}, {"text": "Niedrige Latenz", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Design", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DaaS ist abonnementbasiert. b) Es ersetzt lokale PCs komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "PCs bleiben oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DaaS für IT-Teams?', 5, '[{"text": "Weniger Wartung", "correct": true, "because": "Cloud verwaltet"}, {"text": "Schnelle Bereitstellung", "correct": true, "because": "Keine Hardware-Setup"}, {"text": "Lokale Backups", "correct": false, "because": "Cloud-Backups"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DaaS unwichtig?', 3, '[{"text": "Verfügbarkeit", "correct": false, "because": "Kernmerkmal"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Nutzung"}, {"text": "Lokale Taktfrequenz", "correct": true, "because": "Cloud-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht DaaS immer eine stabile Verbindung?', 3, '[{"text": "Ja", "correct": true, "because": "Cloud-Zugriff erfordert Internet"}, {"text": "Nein", "correct": false, "because": "Offline unbrauchbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DaaS auch für temporäre Projekte geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Schnell skalierbar"}, {"text": "Nein", "correct": false, "because": "Flexibilität gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für DaaS entscheidend?', 4, '[{"text": "Virtuelle Desktops", "correct": true, "because": "Kern der Technologie"}, {"text": "Lokale Installation", "correct": false, "because": "Cloud-basiert"}, {"text": "Hohe Pin-Anzahl", "correct": false, "because": "Hardware-irrelevant"}]');
